  ('schoowa', 'Schoowa', 'der', '', '', 'Grundwortschatz Wienerisch', 'Schober', '[{"kategorie": "wörtlich", "text": "\"Schober\" (vom mittelhochdeutschen \"schober\"=\"Haufen\" bzw. \"Klumpen\")"}, {"kategorie": "Landwirtschaft", "text": "\"im Freien aufgeschichteter, hoher Strohhaufen\", \"Heuhaufen\", (Deutschland): \"Feimen\""}, {"kategorie": "techn., hist.", "text": "deutsches Stückmaß für Stroh (1 Schober = 60 Bund/Garben Stroh), \"Bundmaß\", \"Garbenmaß\", \"Strohbund-Einheit\""}, {"kategorie": "", "text": "\"Feldscheune\", \"Lagerhalle für Heu oder Getreide\", [[Stadel]]"}, {"kategorie": "allg.", "text": "Haufen, Stapel, Bündel, Berg"}]'::jsonb, 'Da Wind is in Schoowa einegfoan und hods trockane Hei davootroong!'),
