  ('sommagschbritzda', 'Sommagschbritzda', 'der', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Sommergespritzter', '[{"kategorie": "wörtlich", "text": "\"Sommergespritzter\" (Determinativkompositum aus \"Sommer\"=\"heiße Jahreszeit\" und \"Gespritzter\"=\"Spritzwein\")"}, {"kategorie": "Gastronomie", "text": "\"gespritzter Weißwein mit höherem Sodawasseranteil\" (d.h. Weißwein, der mehr als zur Hälfte mit Sodawasser aufgespritzt und dadurch weniger alkoholhältig ist), (Deutschland) \"Weißweinschorle mit größerem Sodawasser- als Weinanteil\", [[Sommaschbritza]]"}]'::jsonb, 'Bei dera Hitz sauf I nua Sommagschbritzde - sunst foid ned da Peegl, sondan I!'),
  ('sommaschbritza', 'Sommaschbritza', 'der', '', '', 'Grundwortschatz Wienerisch', 'Sommerspritzer', '[{"kategorie": "wörtlich", "text": "\"Sommerspritzer\" (Determinativkompositum aus \"Sommer\"=\"heiße Jahreszeit\" und \"Spritzer\"=\"Spritzwein\")"}, {"kategorie": "Gastronomie", "text": "\"gespritzter Weißwein mit höherem Sodawasseranteil\" (d.h. Weißwein, der mehr als zur Hälfte mit Sodawasser aufgespritzt und dadurch weniger alkoholhältig ist), (Deutschland) \"Weißweinschorle mit größerem Sodawasser- als Weinanteil\", [[Sommagschbritzda]]"}]'::jsonb, 'Sommaschbritza kaunnsd endlos saufn - des is nua mit Wei vadünnts Wossa!'),
